    B_TOKEN: "two@at@signs.example",          // two @
    C_TOKEN: "[REDACTED sk-l 28 chars]",  // ordinary opaque token
  }).map((s) => s.name).sort();
  assert.deepEqual(got, ["A_TOKEN", "B_TOKEN", "C_TOKEN"]);
});

'''
