dec = b'Dale\xcc\x81n'      # decomposed: e + COMBINING ACUTE
pre = b'Dal\xc3\xa9n'       # precomposed: e-acute
plain = b'Dalen'
hits={'decomposed':[], 'precomposed':[], 'plain':[]}
